Theorem (Congruence of Angle Complements):
Given two angles \(A, B\) and \(A1, B1\) with their respective definitions and the congruence of their sum with respect to a common point \(B\), it follows that the congruence of the sum of the angles \(C\) and \(B\) with respect to a common point \(C\) is equivalent to the congruence of the sum of the angles \(C1\) and \(B1\) with respect to the same common point \(C1\).

theorem (in Congruence_Rule) Ang_complementary :
  assumes
    "Def (Ang (An A B C))"
    "Def (Ang (An A1 B1 C1))"
    "Cong (Geos (Ang (An A B C)) add Emp) (Geos (Ang (An A1 B1 C1)) add Emp)"
    "Bet_Point (Se A D) B"
    "Bet_Point (Se A1 D1) B1"
  shows
    "Cong (Geos (Ang (An C B D)) add Emp) (Geos (Ang (An C1 B1 D1)) add Emp)"
proof -
  from assms have "∃p. Cong (Geos (Ang (An A B C)) add Emp) (Geos (Ang (An p B1 C1)) add Emp)
    ∧ Eq (Geos (Ang (An A1 B1 C1)) add Emp) (Geos (Ang (An p B1 C1)) add Emp)
    ∧ Eq (Geos (Seg (Se B A)) add Emp) (Geos (Seg (Se B1 p)) add Emp)
    ∧ Line_on (Li B1 A1) p ∧ ¬ Bet_Point (Se p A1) B1 ∧ Def (Ang (An p B1 C1))" by (simp add:Ang_replace)
  then obtain A2 :: Point where P1 : "Cong (Geos (Ang (An A B C)) add Emp) (Geos (Ang (An A2 B1 C1)) add Emp) 
    ∧ Eq (Geos (Seg (Se B A)) add Emp) (Geos (Seg (Se B1 A2)) add Emp) ∧ Line_on (Li B1 A1) A2
    ∧ ¬ Bet_Point (Se A2 A1) B1 ∧ Def (Ang (An A2 B1 C1))" by blast
  from assms P1 have "∃p. Cong (Geos (Ang (An A B C)) add Emp) (Geos (Ang (An A2 B1 p)) add Emp)
    ∧ Eq (Geos (Ang (An A2 B1 C1)) add Emp) (Geos (Ang (An A2 B1 p)) add Emp) 
    ∧ Eq (Geos (Seg (Se B C)) add Emp) (Geos (Seg (Se B1 p)) add Emp) 
    ∧ Line_on (Li B1 C1) p ∧ ¬ Bet_Point (Se p C1) B1 ∧ Def (Ang (An A2 B1 p))" by (simp add:Ang_replace)
  then obtain C2 :: Point where P2 : "Cong (Geos (Ang (An A B C)) add Emp) (Geos (Ang (An A2 B1 C2)) add Emp) 
    ∧ Eq (Geos (Seg (Se B C)) add Emp) (Geos (Seg (Se B1 C2)) add Emp) ∧ Line_on (Li B1 C1) C2
    ∧ ¬ Bet_Point (Se C2 C1) B1 ∧ Def (Ang (An A2 B1 C2))" by blast
  from assms have "Def (Tri (Tr A B C))" by (simp add:Ang_to_Tri)
  then have P3 : "Def (Tri (Tr B A C))" by (blast intro:Tri_def_rev Tri_def_trans)
  from P2 have "Def (Tri (Tr A2 B1 C2))" by (simp add:Ang_to_Tri)
  then have P4 : "Def (Tri (Tr B1 A2 C2))" by (blast intro:Tri_def_rev Tri_def_trans)
  from P1 P2 P3 P4 have P5 : "Cong (Geos (Tri (Tr B A C)) add Emp) (Geos (Tri (Tr B1 A2 C2)) add Emp)" by (simp add:Tri_SAS)
  then have P6 : "Eq (Geos (Seg (Se A C)) add Emp) (Geos (Seg (Se A2 C2)) add Emp)" by (simp add:Tri_Cong_def)
  from P5 have P7 : "Cong (Geos (Ang (An C A B)) add Emp) (Geos (Ang (An C2 A2 B1)) add Emp)" by (simp add:Tri_Cong_def)
  have P8 : "Line_on (Li B1 D1) B1" by (simp add:Line_on_rule)
  from assms have P9 : "Line_on (Li A1 D1) B1" by (simp add:Line_Bet_on)
  from assms have p10 : "¬ Eq (Geos (Poi B1) add Emp) (Geos (Poi A1) add Emp)" by (simp add:Bet_Point_def)
  from assms have P11 : "Line_on (Li B1 A1) D1" by (simp add:Line_Bet_on)
  have P12 : "Line_on (Li B1 D1) D1" by (simp add:Line_on_rule)
  have P13 : "Line_on (Li B1 A1) B1" by (simp add:Line_on_rule)
  from assms have P14 : "¬ Eq (Geos (Poi D1) add Emp) (Geos (Poi B1) add Emp)" by (simp add:Bet_Point_def)
  from P8 P11 P12 P13 P14 have P15 : "Eq (Geos (Lin (Li B1 A1)) add Emp) (Geos (Lin (Li B1 D1)) add Emp)" by (simp add:Line_unique)
  from P1 P15 have P16 : "Line_on (Li B1 D1) A2" by (simp add:Line_on_trans)
  from P4 have P17 : "¬ Eq (Geos (Poi B1) add Emp) (Geos (Poi A2) add Emp)" by (simp add:Tri_def)
