  from assms have P8 : "Bet_Point (Se D A) B" by (simp add:Bet_rev)
  from assms P5 P6 P7 P8 have P9 : "Cong (Geos (Ang (An D B E)) add Emp) (Geos (Ang (An C B A)) add Emp)" by (simp add:Ang_complementary)
