Theorem (Equality of Subgroup Orbits and Subgroups of Size \(p^a\):
Given a subgroup \(P\) that is a member of the set of subgroups of size \(p^a\), where \(p\) is a prime and \(a\) is a positive integer, the set of orbits under the conjugation action of \(G\) on \(p^a\) is equal to the set of subgroups of size \(p^a\) itself.

theorem num_eq_card_orbit:
  assumes P:"P ∈ subgroups_of_size (p ^ a)"
  shows "subgroups_of_size (p ^ a) = group_action.orbit G (conjugation_action (p ^ a)) (subgroups_of_size (p ^ a)) P"
proof(auto)
  from finite_G interpret conj: group_action G "(conjugation_action (p ^ a))" "(subgroups_of_size (p ^ a))" by (rule acts_on_subsets)
  have "group_action.orbit G (conjugation_action (p ^ a)) (subgroups_of_size (p ^ a)) P = group_action.same_orbit_rel G (conjugation_action (p ^ a)) (subgroups_of_size (p ^ a)) `` {P}" by (rule conj.orbit_def)
  fix Q
  {
    assume Q:"Q ∈ subgroups_of_size (p ^ a)"
    from P Q obtain g where g:"g ∈ carrier G" "Q = g <# (P #> inv g) " by (rule sylow_conjugate)
    with P conj.orbit_char show "Q ∈ group_action.orbit G (conjugation_action (p ^ a)) (subgroups_of_size (p ^ a)) P"
      unfolding conjugation_action_def by auto
  } {
    assume "Q ∈ group_action.orbit G (conjugation_action (p ^ a)) (subgroups_of_size (p ^ a)) P"
    with P conj.orbit_char obtain g where g:"g ∈ carrier G" "Q = conjugation_action (p ^ a) g P" by auto
    with finite_G P show "Q ∈ subgroups_of_size (p ^ a)"  by (metis conjugation_is_size_invariant)
  }
qed

Theorem (Uniqueness of Prime Factorization):
For any two sets of prime numbers, if each prime in one set is also a prime in the other, then the first set is a subset of the second. In other words, if every prime factor of a number belongs to a second set of primes, then the original set of prime factors must be contained within the second set.

theorem factorization_unique_aux:
  "∀p∈#M. prime p ⟹ ∀p∈#N. prime p ⟹ (∏i∈#M. i) dvd (∏i∈#N. i) ⟹ M ⊆# N"
@proof
  @strong_induct M arbitrary N
  @case "M = {#}"
  @obtain M' m where "M = M' + {#m#}"
  @have "m dvd (∏i∈#M. i)"
  @obtain n where "n ∈# N" "m dvd n"
  @obtain N' where "N = N' + {#n#}"
  @have "m = n"
  @have "(∏i∈#M'. i) dvd (∏i∈#N'. i)"
  @apply_induct_hyp M' N'
@qed

Theorem (Infinitude of Prime Numbers):
The set of prime numbers is not finite, meaning there are infinitely many prime numbers.

theorem primes_infinite: "¬ finite {p. prime p}"
@proof
  @obtain b where "prime b" "Max {p. prime p} < b"
@qed

