Theorem (Existence of a Bigger Prime Number):
There exists a prime number \(p\) such that \(p\) is greater than any given natural number \(n\).

theorem bigger_prime [resolve]: "∃p. prime p ∧ n < p"
@proof
  @obtain p where "prime p" "p dvd fact n + 1"
  @case "n ≥ p" @with @have "(p::nat) dvd fact n" @end
@qed
